// Parse datasets/credential_expiry.json (fetched as text by DownloadTemplate) into a
// single validated item that every downstream node reads via
// $('parse_expiry_config').first().json. Missing keys fall back to defaults, so a
// partial config file can never take the run down.
//
// This file holds policy only - thresholds, the words that mark a date as an expiry,
// and per-type token lifetimes. It deliberately holds no list of credentials: the
// dates come from the credentials themselves, so nothing here goes stale when a
// credential is added, renamed or deleted.
const raw = $json.output || '{}';
let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/credential_expiry.json is not valid JSON: ' + e.message);
}

const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const bool = (v, d) => (typeof v === 'boolean' ? v : d);
const arr = (v, d) => (Array.isArray(v) ? v : d);
const obj = (v, d) => (v && typeof v === 'object' && !Array.isArray(v) ? v : d);
const str = (v, d) => (typeof v === 'string' ? v : d);
const patterns = (v, d) => arr(v, d).map((p) => String(p)).filter((p) => p.length > 0);

const DEFAULT_LABELS = [
  'expir\\w*',
  'caduc\\w*',
  'vence\\w*',
  'valid[\\s_-]*(?:until|to|thru|through)',
  'not[\\s_-]*after',
  'renew(?:al)?[\\s_-]*(?:by|on|date)?',
  'rotate[\\s_-]*(?:by|on)?',
  'eol',
];

// Words that mean a date is NOT a deadline. Without these, "Created 2024-03-01" reads
// as expired 800 days ago.
const DEFAULT_NON_LABELS = [
  'creat\\w*',
  'cread\\w*',
  'added',
  'issued',
  'generated',
  'rotated',
  'updated',
  'since',
  'from',
  'desde',
  'v\\d*',
];

const out = {
  warn_within_days: Math.max(0, num(cfg.warn_within_days, 7)),
  urgent_within_days: Math.max(0, num(cfg.urgent_within_days, 3)),
  critical_within_days: Math.max(0, num(cfg.critical_within_days, 1)),
  notify_when_clean: bool(cfg.notify_when_clean, false),
  report_untracked: bool(cfg.report_untracked, true),
  slack_mention: str(cfg.slack_mention, ''),
  timezone: str(cfg.timezone, 'Europe/Madrid'),
  day_first: bool(cfg.day_first, true),
  label_max_gap: Math.max(0, num(cfg.label_max_gap, 24)),
  accept_bare_iso_dates: bool(cfg.accept_bare_iso_dates, true),
  expirable_type_patterns: patterns(cfg.expirable_type_patterns, ['oauth']),
  test_type_patterns: patterns(cfg.test_type_patterns, ['.*']),
  expiry_label_patterns: patterns(cfg.expiry_label_patterns, DEFAULT_LABELS),
  non_expiry_label_patterns: patterns(cfg.non_expiry_label_patterns, DEFAULT_NON_LABELS),
  ignore_name_patterns: patterns(cfg.ignore_name_patterns, []),
  type_lifetime_days: obj(cfg.type_lifetime_days, {}),
};

// The bands have to nest, otherwise a wider band would shadow a narrower one and
// everything would report as WARNING.
out.urgent_within_days = Math.min(out.urgent_within_days, out.warn_within_days);
out.critical_within_days = Math.min(out.critical_within_days, out.urgent_within_days);

return [{ json: out }];

// GET /credentials is cursor paginated, so the HTTP node emits one item per page and
// each page holds a `data` array. Flatten to one item per credential: the optional
// test_credentials node needs one input item per credential to test.
const pages = $input.all().map((i) => i.json || {});
const raw = pages.flatMap((p) => (Array.isArray(p.data) ? p.data : p && p.id ? [p] : []));

if (!raw.length) {
  throw new Error(
    'GET /credentials returned no credentials. The endpoint needs the credential:list scope - ' +
      'check that the "n8n account" API credential belongs to an instance owner or admin.'
  );
}

const seen = new Set();
const out = [];
for (const c of raw) {
  if (!c || !c.id || seen.has(c.id)) continue;
  seen.add(c.id);
  const owner = Array.isArray(c.shared) ? c.shared.find((s) => s.role === 'credential:owner') : null;
  // n8n names a personal project "<first> <last> <email>", which on a single-owner
  // instance reads as "no name <admin@example.com>" and tells the reader nothing.
  // Only a real team project earns a line in the digest.
  const projectName = owner && owner.name ? String(owner.name).trim() : '';
  out.push({
    json: {
      id: String(c.id),
      name: c.name || '(unnamed)',
      type: c.type || 'unknown',
      createdAt: c.createdAt || null,
      updatedAt: c.updatedAt || null,
      project: /<[^>]+@[^>]+>/.test(projectName) ? '' : projectName,
    },
  });
}

console.log('flatten_credentials: ' + out.length + ' credential(s) from ' + pages.length + ' page(s)');
return out;

// Which credentials to hit with POST /credentials/{id}/test.
//
// Worth knowing before narrowing this: n8n's test is not one mechanism but two.
// A credential type carrying its own `test` block (slackApi, githubApi, n8nApi, most
// API-key types) gets a real HTTP call to the provider, with rules applied to the
// response - that genuinely proves the key still works. A type descending from
// oAuth2Api (linkedInOAuth2Api, gmailOAuth2, googleSheetsOAuth2Api) gets
// CredentialsTester's oauth2CredTest instead, which is only:
//
//     'access_token' in credentialsDecrypted.data.oauthTokenData
//
// No provider call, no expiry check. An access token that died months ago still
// answers OK. So testing OAuth credentials costs nothing and proves nothing, while
// testing API keys costs one request and proves a lot - the opposite of what the word
// "expirable" suggests. Default is therefore everything; evaluate_expiry labels which
// kind of answer each result was.
const cfg = $('parse_expiry_config').first().json;
const creds = $input.all().map((i) => i.json);

const compile = (list) =>
  list
    .map((p) => {
      try {
        return new RegExp(p, 'i');
      } catch (e) {
        console.log('filter_testable: ignoring invalid pattern ' + p + ': ' + e.message);
        return null;
      }
    })
    .filter(Boolean);

const testRx = compile(cfg.test_type_patterns);
const out = creds.filter((c) => testRx.some((r) => r.test(String(c.type || ''))));

console.log(
  'filter_testable: testing ' + out.length + ' of ' + creds.length + ' credential(s): ' + out.map((c) => c.type).join(', ')
);

// An empty list would stop the chain and with it the digest, so the node carries
// alwaysOutputData; the empty item it emits costs one harmless 404 that is discarded.
return out.map((c) => ({ json: c }));

// Work out what expires when, and how urgently, without keeping a list of
// credentials anywhere.
//
// Where the dates come from: no n8n endpoint returns an expiry timestamp - credential
// data is redacted on every API path and oauthTokenData is blanked outright - so the
// real token expiry only exists inside the encrypted blob. What is readable is the
// credential's own name, which is also the one field a human controls, so the date is
// taken from there: an expiry word (expires, caducidad, vence, valid until, not after,
// renew by, eol - all configurable) next to a date, or a bare unambiguous ISO date.
// Types whose tokens have a fixed lifetime and no refresh get their date derived from
// the last re-auth instead, via type_lifetime_days.
//
// What the credential test adds, and what it does not: n8n has two test paths. A type
// with its own `test` block (most API-key types) gets a real HTTP call to the provider,
// so an OK there means the key still works. A type descending from oAuth2Api gets
// CredentialsTester's oauth2CredTest, which is only `'access_token' in oauthTokenData`
// - no provider call, no expiry check - so an OK there means "connected at some point"
// and nothing more. Both arrive as {status, message} on the same endpoint, so this node
// labels them apart rather than reporting a presence check as a verified credential.
const cfg = $('parse_expiry_config').first().json;
const creds = $('flatten_credentials').all().map((i) => i.json);

const TZ = cfg.timezone || 'Europe/Madrid';
const now = DateTime.now().setZone(TZ);
const today = now.startOf('day');

const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();

const compile = (patternList, flags) =>
  patternList
    .map((p) => {
      try {
        return new RegExp(p, flags);
      } catch (e) {
        console.log('evaluate_expiry: ignoring invalid pattern ' + p + ': ' + e.message);
        return null;
      }
    })
    .filter(Boolean);

const ignoreRx = compile(cfg.ignore_name_patterns, 'i');

// One list, two consequences: these are the types that can expire (worth chasing for a
// date) and equally the types whose test proves nothing (oauth2CredTest). That overlap
// is not a coincidence - n8n cannot verify precisely what it cannot date.
const expirableRx = compile(cfg.expirable_type_patterns, 'i');
const isOauthType = (t) => expirableRx.some((r) => r.test(String(t || '')));
const canExpire = (t) => isOauthType(t) || cfg.type_lifetime_days[t] != null;

// Every upstream node is read by name rather than through $input, because the probe
// nodes in between run executeOnce and would otherwise collapse the item stream.
// A node that was skipped or disabled throws on reference, so it degrades to empty.
const safeAll = (node) => {
  try {
    return $(node)
      .all()
      .map((i) => i.json || {});
  } catch (e) {
    return [];
  }
};

// Test responses line up with filter_testable's output rather than the full credential
// list. A credential item always carries an id and a test response never does, which is
// what tells a real response apart from a pass-through when test_credentials is off.
const tested = $('filter_testable')
  .all()
  .map((i) => i.json)
  .filter((c) => c && c.id);

const rawTests = safeAll('test_credentials');
const responses = rawTests.length === tested.length && rawTests.every((j) => j && j.id === undefined) ? rawTests : [];

// A test response is only trustworthy when it carries a status. Anything else - a 403
// because the API key lacks credential:read, a timeout, an HTML error page - means the
// credential was not checked, which must never be reported as "not broken": that turns
// a silent misconfiguration into a clean bill of health.
const readTest = (raw) => {
  if (!raw) return { ran: false, status: null, message: '', http: null };
  const http = typeof raw.statusCode === 'number' ? raw.statusCode : null;
  const body = raw.body !== undefined ? raw.body : raw;
  if (body && typeof body === 'object' && typeof body.status === 'string') {
    return { ran: true, status: body.status, message: String(body.message || ''), http };
  }
  const message =
    (body && typeof body === 'object' && (body.message || (body.error && (body.error.message || body.error)))) ||
    (typeof body === 'string' ? body : '') ||
    'no status in response';
  return { ran: false, status: null, message: String(message), http };
};

// Responses come back in the order they were sent, so index maps them onto the tested
// subset; keying by credential id from there keeps the lookup honest.
const testByCredId = new Map();
tested.forEach((c, i) => {
  if (responses[i] !== undefined) testByCredId.set(String(c.id), readTest(responses[i]));
});

// One probe per expirable credential type: a real request to the provider using that
// credential, which is the only thing that can prove a token is still alive. n8n's own
// test cannot - for OAuth types it just checks that an access_token is stored.
//
// Reading the result is mostly about not crying wolf. Any HTTP answer at all means the
// auth pipeline worked, including 403 (authenticated, wrong scope) and 404 (wrong path):
// those prove the token is good. Only an outright rejection - 401, or an invalid_grant
// from a refresh that failed - means expired. Provider outages and rate limits are
// inconclusive and must stay silent, or the digest becomes noise nobody reads.
// n8n resolves a node's credential by literal id - node.credentials[type].id is read
// raw, with no expression layer, and getCredentialsEntity throws CredentialMissingIdError
// without it - so a probe cannot pick its credential at run time. The id below is
// therefore fixed, but it is never trusted blindly: the live credential list is the
// authority, and a binding that no longer matches is reported with the id to use.
const PROBES = [
  {
    node: 'probe_linkedin',
    type: 'linkedInOAuth2Api',
    credentialId: 'dNaa8BbpK1D8IDZZ',
    endpoint: 'api.linkedin.com/v2/userinfo',
  },
  {
    node: 'probe_gmail',
    type: 'gmailOAuth2',
    credentialId: 'GVSyKsDywK5nuwNG',
    endpoint: 'gmail.googleapis.com/gmail/v1/users/me/profile',
  },
  {
    node: 'probe_google_sheets',
    type: 'googleSheetsOAuth2Api',
    credentialId: 'pGARJmt50qz64xOo',
    endpoint: 'googleapis.com/drive/v3/about',
  },
];

const EXPIRED_MARKERS =
  /invalid_grant|invalid_token|token (?:has been )?(?:expired|revoked)|expired or revoked|needs to be reconnected|reauthorize|re-authenticate|refresh token/i;
const UNCONFIGURED_MARKERS = /credentials? (?:not|could not be) (?:found|set|selected)|no credential|credential id/i;

const classifyProbe = (raw) => {
  if (!raw) return { verdict: 'inconclusive', detail: 'no response' };
  const http = typeof raw.statusCode === 'number' ? raw.statusCode : null;
  const body = raw.body !== undefined ? raw.body : raw;
  const bodyText = typeof body === 'string' ? body : JSON.stringify(body || {});
  const errText = raw.error ? String(raw.error.message || raw.error) : '';
  const blob = errText + ' ' + bodyText;

  if (UNCONFIGURED_MARKERS.test(errText)) return { verdict: 'unconfigured', detail: errText.slice(0, 200) };
  if (EXPIRED_MARKERS.test(blob)) return { verdict: 'expired', detail: (errText || bodyText).slice(0, 200), http };
  if (http !== null) {
    if (http >= 200 && http < 300) return { verdict: 'live', detail: 'HTTP ' + http, http };
    if (http === 401) return { verdict: 'expired', detail: 'HTTP 401 - the provider rejected the token', http };
    if (http === 403) return { verdict: 'live', detail: 'HTTP 403 - authenticated, scope too narrow', http };
    if (http === 404) return { verdict: 'live', detail: 'HTTP 404 - authenticated, endpoint moved', http };
    if (http === 429 || http >= 500) return { verdict: 'inconclusive', detail: 'HTTP ' + http + ' at the provider', http };
    return { verdict: 'inconclusive', detail: 'HTTP ' + http, http };
  }
  return { verdict: 'inconclusive', detail: (errText || 'no status code').slice(0, 200) };
};

const probeById = new Map();
const probeDrift = [];
const unprobedTypes = [];

for (const p of PROBES) {
  const liveOfType = creds.filter((c) => String(c.type) === p.type);
  const boundStillExists = liveOfType.some((c) => String(c.id) === p.credentialId);
  const items = safeAll(p.node);

  if (!liveOfType.length) continue; // type not in this instance - probe is simply idle

  if (!boundStillExists) {
    // Recreating a credential gives it a new id, which would leave this probe testing
    // nothing while looking healthy. Say which id to select instead.
    probeDrift.push({
      node: p.node,
      type: p.type,
      bound: p.credentialId,
      should_be: liveOfType.map((c) => c.name + ' (' + c.id + ')').join(', '),
    });
    continue;
  }

  if (!items.length) continue;
  probeById.set(p.credentialId, { ...classifyProbe(items[0]), node: p.node, endpoint: p.endpoint });

  // More credentials of this type than probes: the extras are dated but never verified.
  for (const extra of liveOfType.filter((c) => String(c.id) !== p.credentialId)) {
    unprobedTypes.push({ name: extra.name, type: extra.type });
  }
}

const DATE_SHAPES = [
  // Only shapes that cannot be misread. 4-digit-first is always year-month-day; the
  // 4-digit-last form follows day_first (true for Europe), because 03/08/2026 is
  // genuinely ambiguous and guessing wrong moves a deadline by months.
  { rx: '(\\d{4})[-/.](\\d{1,2})[-/.](\\d{1,2})', order: 'ymd', iso: true },
  { rx: '(\\d{1,2})[-/.](\\d{1,2})[-/.](\\d{4})', order: cfg.day_first ? 'dmy' : 'mdy', iso: false },
];

const labelSource = cfg.expiry_label_patterns.length ? '(?:' + cfg.expiry_label_patterns.join('|') + ')' : null;
const vetoSource = cfg.non_expiry_label_patterns.length ? '(?:' + cfg.non_expiry_label_patterns.join('|') + ')' : null;

const findDates = (text) => {
  const found = [];
  for (const shape of DATE_SHAPES) {
    const rx = new RegExp(shape.rx, 'g');
    let m;
    while ((m = rx.exec(text)) !== null) {
      const a = Number(m[1]);
      const b = Number(m[2]);
      const c = Number(m[3]);
      const parts =
        shape.order === 'ymd'
          ? { year: a, month: b, day: c }
          : shape.order === 'dmy'
            ? { year: c, month: b, day: a }
            : { year: c, month: a, day: b };
      const dt = DateTime.fromObject(parts, { zone: TZ });
      // A bare date is valid through the end of that day: 2026-08-01 must not read as
      // already expired at 08:00 on the 1st.
      if (dt.isValid) found.push({ dt: dt.endOf('day'), index: m.index, text: m[0], iso: shape.iso });
    }
  }
  return found.sort((x, y) => x.index - y.index);
};

const labelsIn = (subject, source, kind) => {
  if (!source) return [];
  const out = [];
  const rx = new RegExp(source, 'gi');
  let m;
  while ((m = rx.exec(subject)) !== null) {
    out.push({ end: m.index + m[0].length, word: m[0], kind });
    if (m.index === rx.lastIndex) rx.lastIndex++;
  }
  return out;
};

// A date wins if an expiry word sits just before it, and loses if a word like "created"
// or "issued" sits closer - "Created 2024-03-01 legacy webhook" is a birthday, not a
// deadline, and reporting it as expired 800 days ago would be worse than saying nothing.
// With no word either way, a bare ISO date counts, since nothing else in a credential
// name looks like 2026-08-01, while a bare 01/08/2026 could be anything.
const findExpiryInText = (text) => {
  const subject = String(text || '');
  if (!subject) return null;

  const dates = findDates(subject);
  if (!dates.length) return null;

  const labels = labelsIn(subject, labelSource, 'expiry')
    .concat(labelsIn(subject, vetoSource, 'veto'))
    .sort((a, b) => a.end - b.end);

  for (const d of dates) {
    const near = labels
      .filter((l) => d.index >= l.end && d.index - l.end <= cfg.label_max_gap)
      .sort((a, b) => b.end - a.end)[0];

    if (near && near.kind === 'expiry') return { dt: d.dt, matched: d.text, label: near.word };
    if (near) continue;
    if (cfg.accept_bare_iso_dates && d.iso) return { dt: d.dt, matched: d.text, label: null };
  }

  return null;
};

const findings = [];
const untracked = [];
const ignored = [];
const notExpirable = [];
const testUnavailable = [];
let okCount = 0;
let verifiedCount = 0;
let tokenPresentCount = 0;
const staleDates = [];

creds.forEach((c) => {
  if (ignoreRx.some((rx) => rx.test(String(c.name || '')))) {
    ignored.push({ name: c.name, type: c.type });
    return;
  }

  const expirable = canExpire(c.type);
  const presenceOnly = isOauthType(c.type);
  const test = testByCredId.get(String(c.id)) || null;
  const probe = probeById.get(String(c.id)) || null;
  const probeExpired = !!probe && probe.verdict === 'expired';
  // A provider rejection is proof, so it outranks any date and any presence check.
  const broken = probeExpired || (!!test && test.ran && norm(test.status) !== 'ok');

  let testVerdict = null;
  if (test && !test.ran) {
    // No verdict came back, so this credential was NOT checked.
    testVerdict = 'unavailable';
    testUnavailable.push({
      name: c.name,
      type: c.type,
      http: test.http,
      message: String(test.message || '').slice(0, 200),
    });
  } else if (test && test.ran && !broken) {
    // An OAuth type only proves a token is stored; anything else made a real call.
    testVerdict = presenceOnly ? 'token_present' : 'verified';
    if (presenceOnly) tokenPresentCount++;
    else verifiedCount++;
  } else if (broken) {
    testVerdict = 'failed';
  }

  let expiresAt = null;
  let expirySource = null;

  const hit = findExpiryInText(c.name);
  if (hit) {
    expiresAt = hit.dt;
    expirySource = hit.label ? 'name: "' + hit.label + ' ' + hit.matched + '"' : 'name: ' + hit.matched;
  } else {
    const lifetime = Number(cfg.type_lifetime_days[c.type]);
    const updated = c.updatedAt ? DateTime.fromISO(c.updatedAt, { zone: TZ }) : null;
    if (isFinite(lifetime) && lifetime > 0 && updated && updated.isValid) {
      expiresAt = updated.plus({ days: lifetime }).endOf('day');
      expirySource = lifetime + 'd ' + c.type + ' lifetime from last update ' + updated.toFormat('yyyy-LL-dd');
    }
  }

  const base = {
    probe_verdict: probe ? probe.verdict : null,
    probe_detail: probe ? probe.detail : '',
    probe_endpoint: probe ? probe.endpoint : '',
    credential_id: c.id,
    name: c.name,
    type: c.type,
    project: c.project,
    created_at: c.createdAt,
    updated_at: c.updatedAt,
    expiry_source: expirySource,
    can_expire: expirable,
    presence_check_only: presenceOnly,
    broken,
    test_verdict: testVerdict,
    test_status: test ? (test.ran ? test.status : 'Unavailable') : null,
    test_message: broken ? String(test.message || '').slice(0, 300) : '',
  };

  if (!expiresAt) {
    // No date to reason about. A failed test still makes it actionable today: for an
    // OAuth credential a failure means n8n holds no access token at all, so it was
    // never connected or was cleared - broken now, whatever any date would have said.
    if (probeExpired) {
      findings.push({ ...base, band: 'EXPIRED', expires_at: null, expires_on: null, days_left: null, sort_key: -2e6 });
    } else if (broken) {
      findings.push({ ...base, band: 'BROKEN', expires_at: null, expires_on: null, days_left: null, sort_key: -1e6 });
    } else if (expirable) {
      untracked.push({ credential_id: c.id, name: c.name, type: c.type });
    } else {
      // A plain API key has no expiry to miss, so chasing a date it cannot have would
      // only teach the reader to skim past the list.
      notExpirable.push({ name: c.name, type: c.type });
    }
    return;
  }

  const daysLeft = Math.floor(expiresAt.startOf('day').diff(today, 'days').days);
  let band;
  if (daysLeft < 0) band = 'EXPIRED';
  else if (daysLeft <= cfg.critical_within_days) band = 'CRITICAL';
  else if (daysLeft <= cfg.urgent_within_days) band = 'URGENT';
  else if (daysLeft <= cfg.warn_within_days) band = 'WARNING';
  else band = 'OK';

  // Evidence beats arithmetic. A token the provider just rejected is expired whatever
  // its name says; a token that still authenticates is not expired just because a
  // derived date ran out, and saying otherwise would train the reader to distrust this.
  if (probeExpired) band = 'EXPIRED';
  else if (probe && probe.verdict === 'live' && band === 'EXPIRED') band = 'STALE_DATE';

  if ((band === 'OK' || band === 'STALE_DATE') && !broken) {
    if (band === 'STALE_DATE') staleDates.push({ name: c.name, type: c.type, expires_on: expiresAt.toFormat('yyyy-LL-dd') });
    else okCount++;
    return;
  }

  findings.push({
    ...base,
    band: band === 'OK' ? 'BROKEN' : band,
    expires_at: expiresAt.toISO(),
    expires_on: expiresAt.toFormat('yyyy-LL-dd'),
    days_left: daysLeft,
    // A credential that fails its test is already failing in production, so it leads the
    // digest whatever its paper date says - a token rejected today is not a problem for
    // January. Time order still decides within each group.
    sort_key: probeExpired ? -2e6 + daysLeft : broken ? -1e6 + daysLeft : daysLeft,
  });
});

// Soonest first.
findings.sort((a, b) => a.sort_key - b.sort_key || String(a.name).localeCompare(String(b.name)));

const countBand = (b) => findings.filter((f) => f.band === b).length;
const stats = {
  run_at: now.toISO(),
  timezone: TZ,
  total_credentials: creds.length,
  findings: findings.length,
  expired: countBand('EXPIRED'),
  critical: countBand('CRITICAL'),
  urgent: countBand('URGENT'),
  warning: countBand('WARNING'),
  broken: countBand('BROKEN'),
  ok: okCount,
  untracked: untracked.length,
  ignored: ignored.length,
  not_expirable: notExpirable.length,
  expirable: creds.filter((c) => canExpire(c.type)).length,
  tested: testByCredId.size,
  verified: verifiedCount,
  token_present: tokenPresentCount,
  test_unavailable: testUnavailable.length,
  probes_run: probeById.size,
  probes_live: [...probeById.values()].filter((p) => p.verdict === 'live').length,
  probes_expired: [...probeById.values()].filter((p) => p.verdict === 'expired').length,
  probes_inconclusive: [...probeById.values()].filter((p) => p.verdict === 'inconclusive').length,
  probes_unconfigured: [...probeById.values()].filter((p) => p.verdict === 'unconfigured').length,
  stale_dates: staleDates.length,
  probes_drifted: probeDrift.length,
  unprobed: unprobedTypes.length,
  warn_within_days: cfg.warn_within_days,
  urgent_within_days: cfg.urgent_within_days,
  critical_within_days: cfg.critical_within_days,
};

console.log('evaluate_expiry: ' + JSON.stringify(stats));

const extras = {
  _stats: stats,
  _untracked: untracked,
  _ignored: ignored,
  _not_expirable: notExpirable,
  _test_unavailable: testUnavailable,
  _stale_dates: staleDates,
  _probe_drift: probeDrift,
  _unprobed: unprobedTypes,
  _probes: [...probeById.entries()].map(([id, p]) => ({
    credential_id: id,
    node: p.node,
    endpoint: p.endpoint,
    verdict: p.verdict,
    detail: p.detail,
  })),
};

if (!findings.length) {
  return [{ json: { no_findings: true, ...extras } }];
}

return findings.map((f, i) => ({ json: i === 0 ? { rank: 1, ...f, ...extras } : { rank: i + 1, ...f } }));

// Slack digest. The wording is deliberately different per band: an already dead or
// same-day credential has to read as "drop what you are doing", a 5-day one as a
// heads-up. Same message for both trains the reader to ignore it.
const items = $input.all().map((i) => i.json);
const first = items[0] || {};
const stats = first._stats || {};
const untracked = first._untracked || [];
const ignored = first._ignored || [];
const testUnavailable = first._test_unavailable || [];
const probes = first._probes || [];
const staleDates = first._stale_dates || [];
const probeDrift = first._probe_drift || [];
const unprobed = first._unprobed || [];
const cfg = $('parse_expiry_config').first().json;

const findings = first.no_findings ? [] : items;

const EMOJI = {
  EXPIRED: ':skull:',
  CRITICAL: ':rotating_light:',
  BROKEN: ':x:',
  URGENT: ':warning:',
  WARNING: ':hourglass_flowing_sand:',
};
const SEVERITY = ['EXPIRED', 'CRITICAL', 'BROKEN', 'URGENT', 'WARNING'];
const worst = SEVERITY.find((b) => findings.some((f) => f.band === b)) || null;

const when = (f) => {
  // Provider evidence, when there is any, is the headline - "expires in 2 days" next to a
  // skull reads as a contradiction when the token is already being refused.
  if (f.probe_verdict === 'expired') {
    return (
      '*rejected by the provider right now*' +
      (f.expires_on ? ' (its date said ' + f.expires_on + ')' : '')
    );
  }
  if (f.days_left === null || f.days_left === undefined) return 'no expiry date on record';
  if (f.days_left < 0) return '*expired ' + Math.abs(f.days_left) + ' day(s) ago* (' + f.expires_on + ')';
  if (f.days_left === 0) return '*expires TODAY* (' + f.expires_on + ')';
  if (f.days_left === 1) return '*expires TOMORROW* (' + f.expires_on + ')';
  return 'expires in *' + f.days_left + ' days* (' + f.expires_on + ')';
};

const action = (f) => {
  switch (f.band) {
    case 'EXPIRED':
      return f.probe_verdict === 'expired'
        ? 'The provider rejected this token just now, so every workflow using it is already failing. Reconnect the credential in n8n.'
        : 'Past its date - anything using it is likely failing already. Rotate it now.';
    case 'CRITICAL':
      return 'Rotate today, there is no margin left.';
    case 'BROKEN':
      return f.presence_check_only
        ? 'n8n holds no access token for this credential - it was never connected, or the token was cleared. Reconnect it.'
        : 'The provider rejected it, so it is broken regardless of its date - rotate or re-authenticate it.';
    case 'URGENT':
      return 'Rotate in the next couple of days.';
    default:
      return 'Put the rotation on this week.';
  }
};

const lines = [];

if (!findings.length) {
  lines.push(
    ':white_check_mark: *Credentials Review* - nothing expires within ' +
      stats.warn_within_days +
      ' days' +
      (stats.probes_live ? ', and ' + stats.probes_live + ' expirable credential(s) still authenticate with their provider' : '') +
      (stats.verified ? ', ' + stats.verified + ' API key(s) verified' : '') +
      '.'
  );
} else {
  const mention = cfg.slack_mention && ['EXPIRED', 'CRITICAL', 'BROKEN'].includes(worst) ? cfg.slack_mention + ' ' : '';
  if (worst === 'EXPIRED' || worst === 'CRITICAL' || worst === 'BROKEN') {
    lines.push(
      mention + ':rotating_light: *Credentials Review* - ' + findings.length + ' credential(s) need action *now*'
    );
  } else if (worst === 'URGENT') {
    lines.push(
      ':warning: *Credentials Review* - ' +
        findings.length +
        ' credential(s) expire within ' +
        stats.urgent_within_days +
        ' days'
    );
  } else {
    lines.push(
      ':hourglass_flowing_sand: *Credentials Review* - heads-up, ' +
        findings.length +
        ' credential(s) expire within ' +
        stats.warn_within_days +
        ' days'
    );
  }
  lines.push('');

  for (const f of findings) {
    lines.push((EMOJI[f.band] || ':grey_question:') + ' *' + f.rank + '. ' + f.name + '* - ' + when(f));
    const bits = ['type `' + f.type + '`'];
    if (f.project) bits.push('project ' + f.project);
    if (f.probe_verdict) bits.push('probe ' + f.probe_verdict + (f.probe_detail ? ' (' + f.probe_detail + ')' : ''));
    if (f.expiry_source) bits.push('read from ' + f.expiry_source);
    if (f.broken && f.test_message) bits.push('test: ' + f.test_message);
    lines.push('`' + bits.join('  |  ') + '`');
    lines.push('_' + action(f) + '_');
    lines.push('');
  }
  lines.push('_After rotating, update the date in the credential name and this stops nagging._');

  // A derived date is a guess about when the token was issued, and the reader has to
  // know that before trusting it: n8n never exposes the real expiry, and re-saving a
  // credential without reconnecting bumps updatedAt and silently moves the deadline.
  if (findings.some((f) => String(f.expiry_source || '').includes('lifetime from last update'))) {
    lines.push(
      '_Dates read from a `lifetime` are derived from the credential\'s last update, not from the token - n8n never exposes the real expiry. Editing and saving a credential without reconnecting it restarts that countdown._'
    );
  }
}

lines.push(
  '`' +
    stats.total_credentials +
    ' credentials · ' +
    stats.expired +
    ' expired · ' +
    stats.critical +
    ' critical · ' +
    stats.urgent +
    ' urgent · ' +
    stats.warning +
    ' warning · ' +
    stats.broken +
    ' broken · ' +
    stats.ok +
    ' ok · ' +
    stats.untracked +
    ' undated · ' +
    stats.not_expirable +
    ' cannot expire · ' +
    stats.ignored +
    ' ignored`'
);
lines.push(
  '`tested ' +
    (stats.tested || 0) +
    ' · ' +
    (stats.verified || 0) +
    ' verified with provider · ' +
    (stats.token_present || 0) +
    ' oauth token present but unverified · ' +
    (stats.broken || 0) +
    ' failed' +
    (stats.test_unavailable ? ' · ' + stats.test_unavailable + ' not checked' : '') +
    '`'
);

// The presence check is the single most misleading thing in this digest, so it gets
// said out loud every time it happened rather than buried in a node comment.
if (stats.token_present) {
  lines.push(
    '_`oauth token present but unverified`: for OAuth credentials n8n only checks that an access token is stored, with no call to the provider - a token that died months ago still answers OK. Their dates, not their test result, are the signal._'
  );
}

for (const d of probeDrift) {
  lines.push(
    ':rotating_light: *' +
      d.node +
      ' is bound to a credential that no longer exists* (id `' +
      d.bound +
      '`), so ' +
      d.type +
      ' was not verified at all. Open that node and select: ' +
      d.should_be
  );
}

for (const u of unprobed) {
  lines.push(
    ':grey_exclamation: *' + u.name + '* shares the type ' + u.type + ' with a probed credential, so it is dated but never verified. Give it its own probe node to cover it.'
  );
}

if (probes.length) {
  const byVerdict = (v) => probes.filter((p) => p.verdict === v);
  lines.push(
    '`probes ' +
      probes.length +
      ' · ' +
      byVerdict('live').length +
      ' live · ' +
      byVerdict('expired').length +
      ' expired · ' +
      byVerdict('inconclusive').length +
      ' inconclusive · ' +
      byVerdict('unconfigured').length +
      ' unconfigured`'
  );
  for (const p of byVerdict('unconfigured')) {
    lines.push(
      ':grey_exclamation: *' + p.node + ' has no credential selected* - open that node once in n8n and pick the ' + p.type + ' credential, or this type is never really checked.'
    );
  }
  for (const p of byVerdict('inconclusive')) {
    lines.push(
      ':grey_exclamation: *' + p.type + ' could not be verified this run* - ' + p.detail + ' (' + p.endpoint + '). Not treated as expired; a provider hiccup is not a dead token.'
    );
  }
}

if (staleDates.length) {
  lines.push(
    ':information_source: *Still working despite an expired date* - ' +
      staleDates.map((d) => d.name + ' (dated ' + d.expires_on + ')').join(', ')
  );
  lines.push(
    '_The provider still accepts the token, so the date is what is wrong. It was probably reconnected without updating the name - fix the date and this stops._'
  );
}

if (testUnavailable.length) {
  const first_ = testUnavailable[0];
  lines.push(
    ':grey_exclamation: *' +
      testUnavailable.length +
      ' credential(s) were not actually checked* - ' +
      testUnavailable
        .slice(0, 6)
        .map((u) => u.name)
        .join(', ') +
      (testUnavailable.length > 6 ? ' … +' + (testUnavailable.length - 6) + ' more' : '')
  );
  lines.push(
    '_The test returned no verdict' +
      (first_.http ? ' (HTTP ' + first_.http + ': ' + first_.message + ')' : ': ' + first_.message) +
      '. A 403 means the n8n API key is missing the `credential:read` scope - until that is fixed, silence here does not mean healthy._'
  );
}

if (cfg.report_untracked && untracked.length) {
  const shown = untracked.slice(0, 12).map((u) => u.name + ' (' + u.type + ')');
  lines.push(
    ':question: *No expiry date, but can expire* - ' +
      untracked.length +
      ': ' +
      shown.join(', ') +
      (untracked.length > shown.length ? ' … +' + (untracked.length - shown.length) + ' more' : '')
  );
  lines.push(
    '_A stored token is not a date - n8n only proves one exists, never that it is still good. Rename the credential in n8n to carry its date - `Some account (expires 2026-08-01)` - or add its type to `type_lifetime_days`._'
  );
}

if (!stats.tested) {
  lines.push(
    '_No credential was tested this run: nothing matched `test_type_patterns`, so only dates were checked._'
  );
}

return [
  {
    json: {
      digest_text: lines.join('\n'),
      should_notify: findings.length > 0 || cfg.notify_when_clean === true,
      findings_count: findings.length,
      worst_band: worst,
      _stats: stats,
      _ignored: ignored,
    },
  },
];

// Parse datasets/credential_expiry.json (fetched as text by DownloadTemplate) into a
// single validated item that every downstream node reads via
// $('parse_expiry_config').first().json. Missing keys fall back to defaults, so a
// partial config file can never take the run down.
//
// This file holds policy only - thresholds, the words that mark a date as an expiry,
// and per-type token lifetimes. It deliberately holds no list of credentials: the
// dates come from the credentials themselves, so nothing here goes stale when a
// credential is added, renamed or deleted.
const raw = $json.output || '{}';
let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/credential_expiry.json is not valid JSON: ' + e.message);
}

const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const bool = (v, d) => (typeof v === 'boolean' ? v : d);
const arr = (v, d) => (Array.isArray(v) ? v : d);
const obj = (v, d) => (v && typeof v === 'object' && !Array.isArray(v) ? v : d);
const str = (v, d) => (typeof v === 'string' ? v : d);
const patterns = (v, d) => arr(v, d).map((p) => String(p)).filter((p) => p.length > 0);

const DEFAULT_LABELS = [
  'expir\\w*',
  'caduc\\w*',
  'vence\\w*',
  'valid[\\s_-]*(?:until|to|thru|through)',
  'not[\\s_-]*after',
  'renew(?:al)?[\\s_-]*(?:by|on|date)?',
  'rotate[\\s_-]*(?:by|on)?',
  'eol',
];

// Words that mean a date is NOT a deadline. Without these, "Created 2024-03-01" reads
// as expired 800 days ago.
const DEFAULT_NON_LABELS = [
  'creat\\w*',
  'cread\\w*',
  'added',
  'issued',
  'generated',
  'rotated',
  'updated',
  'since',
  'from',
  'desde',
  'v\\d*',
];

const out = {
  warn_within_days: Math.max(0, num(cfg.warn_within_days, 7)),
  urgent_within_days: Math.max(0, num(cfg.urgent_within_days, 3)),
  critical_within_days: Math.max(0, num(cfg.critical_within_days, 1)),
  notify_when_clean: bool(cfg.notify_when_clean, false),
  report_untracked: bool(cfg.report_untracked, true),
  slack_mention: str(cfg.slack_mention, ''),
  timezone: str(cfg.timezone, 'Europe/Madrid'),
  day_first: bool(cfg.day_first, true),
  label_max_gap: Math.max(0, num(cfg.label_max_gap, 24)),
  accept_bare_iso_dates: bool(cfg.accept_bare_iso_dates, true),
  expirable_type_patterns: patterns(cfg.expirable_type_patterns, ['oauth']),
  test_type_patterns: patterns(cfg.test_type_patterns, ['.*']),
  expiry_label_patterns: patterns(cfg.expiry_label_patterns, DEFAULT_LABELS),
  non_expiry_label_patterns: patterns(cfg.non_expiry_label_patterns, DEFAULT_NON_LABELS),
  ignore_name_patterns: patterns(cfg.ignore_name_patterns, []),
  type_lifetime_days: obj(cfg.type_lifetime_days, {}),
};

// The bands have to nest, otherwise a wider band would shadow a narrower one and
// everything would report as WARNING.
out.urgent_within_days = Math.min(out.urgent_within_days, out.warn_within_days);
out.critical_within_days = Math.min(out.critical_within_days, out.urgent_within_days);

return [{ json: out }];

// GET /credentials is cursor paginated, so the HTTP node emits one item per page and
// each page holds a `data` array. Flatten to one item per credential: the optional
// test_credentials node needs one input item per credential to test.
const pages = $input.all().map((i) => i.json || {});
const raw = pages.flatMap((p) => (Array.isArray(p.data) ? p.data : p && p.id ? [p] : []));

if (!raw.length) {
  throw new Error(
    'GET /credentials returned no credentials. The endpoint needs the credential:list scope - ' +
      'check that the "n8n account" API credential belongs to an instance owner or admin.'
  );
}

const seen = new Set();
const out = [];
for (const c of raw) {
  if (!c || !c.id || seen.has(c.id)) continue;
  seen.add(c.id);
  const owner = Array.isArray(c.shared) ? c.shared.find((s) => s.role === 'credential:owner') : null;
  // n8n names a personal project "<first> <last> <email>", which on a single-owner
  // instance reads as "no name <admin@example.com>" and tells the reader nothing.
  // Only a real team project earns a line in the digest.
  const projectName = owner && owner.name ? String(owner.name).trim() : '';
  out.push({
    json: {
      id: String(c.id),
      name: c.name || '(unnamed)',
      type: c.type || 'unknown',
      createdAt: c.createdAt || null,
      updatedAt: c.updatedAt || null,
      project: /<[^>]+@[^>]+>/.test(projectName) ? '' : projectName,
    },
  });
}

console.log('flatten_credentials: ' + out.length + ' credential(s) from ' + pages.length + ' page(s)');
return out;

// Which credentials to hit with POST /credentials/{id}/test.
//
// Worth knowing before narrowing this: n8n's test is not one mechanism but two.
// A credential type carrying its own `test` block (slackApi, githubApi, n8nApi, most
// API-key types) gets a real HTTP call to the provider, with rules applied to the
// response - that genuinely proves the key still works. A type descending from
// oAuth2Api (linkedInOAuth2Api, gmailOAuth2, googleSheetsOAuth2Api) gets
// CredentialsTester's oauth2CredTest instead, which is only:
//
//     'access_token' in credentialsDecrypted.data.oauthTokenData
//
// No provider call, no expiry check. An access token that died months ago still
// answers OK. So testing OAuth credentials costs nothing and proves nothing, while
// testing API keys costs one request and proves a lot - the opposite of what the word
// "expirable" suggests. Default is therefore everything; evaluate_expiry labels which
// kind of answer each result was.
const cfg = $('parse_expiry_config').first().json;
const creds = $input.all().map((i) => i.json);

const compile = (list) =>
  list
    .map((p) => {
      try {
        return new RegExp(p, 'i');
      } catch (e) {
        console.log('filter_testable: ignoring invalid pattern ' + p + ': ' + e.message);
        return null;
      }
    })
    .filter(Boolean);

const testRx = compile(cfg.test_type_patterns);
const out = creds.filter((c) => testRx.some((r) => r.test(String(c.type || ''))));

console.log(
  'filter_testable: testing ' + out.length + ' of ' + creds.length + ' credential(s): ' + out.map((c) => c.type).join(', ')
);

// An empty list would stop the chain and with it the digest, so the node carries
// alwaysOutputData; the empty item it emits costs one harmless 404 that is discarded.
return out.map((c) => ({ json: c }));

// Work out what expires when, and how urgently, without keeping a list of
// credentials anywhere.
//
// Where the dates come from: no n8n endpoint returns an expiry timestamp - credential
// data is redacted on every API path and oauthTokenData is blanked outright - so the
// real token expiry only exists inside the encrypted blob. What is readable is the
// credential's own name, which is also the one field a human controls, so the date is
// taken from there: an expiry word (expires, caducidad, vence, valid until, not after,
// renew by, eol - all configurable) next to a date, or a bare unambiguous ISO date.
// Types whose tokens have a fixed lifetime and no refresh get their date derived from
// the last re-auth instead, via type_lifetime_days.
//
// What the credential test adds, and what it does not: n8n has two test paths. A type
// with its own `test` block (most API-key types) gets a real HTTP call to the provider,
// so an OK there means the key still works. A type descending from oAuth2Api gets
// CredentialsTester's oauth2CredTest, which is only `'access_token' in oauthTokenData`
// - no provider call, no expiry check - so an OK there means "connected at some point"
// and nothing more. Both arrive as {status, message} on the same endpoint, so this node
// labels them apart rather than reporting a presence check as a verified credential.
const cfg = $('parse_expiry_config').first().json;
const creds = $('flatten_credentials').all().map((i) => i.json);

const TZ = cfg.timezone || 'Europe/Madrid';
const now = DateTime.now().setZone(TZ);
const today = now.startOf('day');

const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();

const compile = (patternList, flags) =>
  patternList
    .map((p) => {
      try {
        return new RegExp(p, flags);
      } catch (e) {
        console.log('evaluate_expiry: ignoring invalid pattern ' + p + ': ' + e.message);
        return null;
      }
    })
    .filter(Boolean);

const ignoreRx = compile(cfg.ignore_name_patterns, 'i');

// One list, two consequences: these are the types that can expire (worth chasing for a
// date) and equally the types whose test proves nothing (oauth2CredTest). That overlap
// is not a coincidence - n8n cannot verify precisely what it cannot date.
const expirableRx = compile(cfg.expirable_type_patterns, 'i');
const isOauthType = (t) => expirableRx.some((r) => r.test(String(t || '')));
const canExpire = (t) => isOauthType(t) || cfg.type_lifetime_days[t] != null;

// Every upstream node is read by name rather than through $input, because the probe
// nodes in between run executeOnce and would otherwise collapse the item stream.
// A node that was skipped or disabled throws on reference, so it degrades to empty.
const safeAll = (node) => {
  try {
    return $(node)
      .all()
      .map((i) => i.json || {});
  } catch (e) {
    return [];
  }
};

// Test responses line up with filter_testable's output rather than the full credential
// list. A credential item always carries an id and a test response never does, which is
// what tells a real response apart from a pass-through when test_credentials is off.
const tested = $('filter_testable')
  .all()
  .map((i) => i.json)
  .filter((c) => c && c.id);

const rawTests = safeAll('test_credentials');
const responses = rawTests.length === tested.length && rawTests.every((j) => j && j.id === undefined) ? rawTests : [];

// A test response is only trustworthy when it carries a status. Anything else - a 403
// because the API key lacks credential:read, a timeout, an HTML error page - means the
// credential was not checked, which must never be reported as "not broken": that turns
// a silent misconfiguration into a clean bill of health.
const readTest = (raw) => {
  if (!raw) return { ran: false, status: null, message: '', http: null };
  const http = typeof raw.statusCode === 'number' ? raw.statusCode : null;
  const body = raw.body !== undefined ? raw.body : raw;
  if (body && typeof body === 'object' && typeof body.status === 'string') {
    return { ran: true, status: body.status, message: String(body.message || ''), http };
  }
  const message =
    (body && typeof body === 'object' && (body.message || (body.error && (body.error.message || body.error)))) ||
    (typeof body === 'string' ? body : '') ||
    'no status in response';
  return { ran: false, status: null, message: String(message), http };
};

// Responses come back in the order they were sent, so index maps them onto the tested
// subset; keying by credential id from there keeps the lookup honest.
const testByCredId = new Map();
tested.forEach((c, i) => {
  if (responses[i] !== undefined) testByCredId.set(String(c.id), readTest(responses[i]));
});

// One probe per expirable credential type: a real request to the provider using that
// credential, which is the only thing that can prove a token is still alive. n8n's own
// test cannot - for OAuth types it just checks that an access_token is stored.
//
// Reading the result is mostly about not crying wolf. Any HTTP answer at all means the
// auth pipeline worked, including 403 (authenticated, wrong scope) and 404 (wrong path):
// those prove the token is good. Only an outright rejection - 401, or an invalid_grant
// from a refresh that failed - means expired. Provider outages and rate limits are
// inconclusive and must stay silent, or the digest becomes noise nobody reads.
// n8n resolves a node's credential by literal id - node.credentials[type].id is read
// raw, with no expression layer, and getCredentialsEntity throws CredentialMissingIdError
// without it - so a probe cannot pick its credential at run time. The id below is
// therefore fixed, but it is never trusted blindly: the live credential list is the
// authority, and a binding that no longer matches is reported with the id to use.
const PROBES = [
  {
    node: 'probe_linkedin',
    type: 'linkedInOAuth2Api',
    credentialId: 'dNaa8BbpK1D8IDZZ',
    endpoint: 'api.linkedin.com/v2/userinfo',
  },
  {
    node: 'probe_gmail',
    type: 'gmailOAuth2',
    credentialId: 'GVSyKsDywK5nuwNG',
    endpoint: 'gmail.googleapis.com/gmail/v1/users/me/profile',
  },
  {
    node: 'probe_google_sheets',
    type: 'googleSheetsOAuth2Api',
    credentialId: 'pGARJmt50qz64xOo',
    endpoint: 'googleapis.com/drive/v3/about',
  },
];

const EXPIRED_MARKERS =
  /invalid_grant|invalid_token|token (?:has been )?(?:expired|revoked)|expired or revoked|needs to be reconnected|reauthorize|re-authenticate|refresh token/i;
const UNCONFIGURED_MARKERS = /credentials? (?:not|could not be) (?:found|set|selected)|no credential|credential id/i;

const classifyProbe = (raw) => {
  if (!raw) return { verdict: 'inconclusive', detail: 'no response' };
  const http = typeof raw.statusCode === 'number' ? raw.statusCode : null;
  const body = raw.body !== undefined ? raw.body : raw;
  const bodyText = typeof body === 'string' ? body : JSON.stringify(body || {});
  const errText = raw.error ? String(raw.error.message || raw.error) : '';
  const blob = errText + ' ' + bodyText;

  if (UNCONFIGURED_MARKERS.test(errText)) return { verdict: 'unconfigured', detail: errText.slice(0, 200) };
  if (EXPIRED_MARKERS.test(blob)) return { verdict: 'expired', detail: (errText || bodyText).slice(0, 200), http };
  if (http !== null) {
    if (http >= 200 && http < 300) return { verdict: 'live', detail: 'HTTP ' + http, http };
    if (http === 401) return { verdict: 'expired', detail: 'HTTP 401 - the provider rejected the token', http };
    if (http === 403) return { verdict: 'live', detail: 'HTTP 403 - authenticated, scope too narrow', http };
    if (http === 404) return { verdict: 'live', detail: 'HTTP 404 - authenticated, endpoint moved', http };
    if (http === 429 || http >= 500) return { verdict: 'inconclusive', detail: 'HTTP ' + http + ' at the provider', http };
    return { verdict: 'inconclusive', detail: 'HTTP ' + http, http };
  }
  return { verdict: 'inconclusive', detail: (errText || 'no status code').slice(0, 200) };
};

const probeById = new Map();
const probeDrift = [];
const unprobedTypes = [];

for (const p of PROBES) {
  const liveOfType = creds.filter((c) => String(c.type) === p.type);
  const boundStillExists = liveOfType.some((c) => String(c.id) === p.credentialId);
  const items = safeAll(p.node);

  if (!liveOfType.length) continue; // type not in this instance - probe is simply idle

  if (!boundStillExists) {
    // Recreating a credential gives it a new id, which would leave this probe testing
    // nothing while looking healthy. Say which id to select instead.
    probeDrift.push({
      node: p.node,
      type: p.type,
      bound: p.credentialId,
      should_be: liveOfType.map((c) => c.name + ' (' + c.id + ')').join(', '),
    });
    continue;
  }

  if (!items.length) continue;
  probeById.set(p.credentialId, { ...classifyProbe(items[0]), node: p.node, endpoint: p.endpoint });

  // More credentials of this type than probes: the extras are dated but never verified.
  for (const extra of liveOfType.filter((c) => String(c.id) !== p.credentialId)) {
    unprobedTypes.push({ name: extra.name, type: extra.type });
  }
}

const DATE_SHAPES = [
  // Only shapes that cannot be misread. 4-digit-first is always year-month-day; the
  // 4-digit-last form follows day_first (true for Europe), because 03/08/2026 is
  // genuinely ambiguous and guessing wrong moves a deadline by months.
  { rx: '(\\d{4})[-/.](\\d{1,2})[-/.](\\d{1,2})', order: 'ymd', iso: true },
  { rx: '(\\d{1,2})[-/.](\\d{1,2})[-/.](\\d{4})', order: cfg.day_first ? 'dmy' : 'mdy', iso: false },
];

const labelSource = cfg.expiry_label_patterns.length ? '(?:' + cfg.expiry_label_patterns.join('|') + ')' : null;
const vetoSource = cfg.non_expiry_label_patterns.length ? '(?:' + cfg.non_expiry_label_patterns.join('|') + ')' : null;

const findDates = (text) => {
  const found = [];
  for (const shape of DATE_SHAPES) {
    const rx = new RegExp(shape.rx, 'g');
    let m;
    while ((m = rx.exec(text)) !== null) {
      const a = Number(m[1]);
      const b = Number(m[2]);
      const c = Number(m[3]);
      const parts =
        shape.order === 'ymd'
          ? { year: a, month: b, day: c }
          : shape.order === 'dmy'
            ? { year: c, month: b, day: a }
            : { year: c, month: a, day: b };
      const dt = DateTime.fromObject(parts, { zone: TZ });
      // A bare date is valid through the end of that day: 2026-08-01 must not read as
      // already expired at 08:00 on the 1st.
      if (dt.isValid) found.push({ dt: dt.endOf('day'), index: m.index, text: m[0], iso: shape.iso });
    }
  }
  return found.sort((x, y) => x.index - y.index);
};

const labelsIn = (subject, source, kind) => {
  if (!source) return [];
  const out = [];
  const rx = new RegExp(source, 'gi');
  let m;
  while ((m = rx.exec(subject)) !== null) {
    out.push({ end: m.index + m[0].length, word: m[0], kind });
    if (m.index === rx.lastIndex) rx.lastIndex++;
  }
  return out;
};

// A date wins if an expiry word sits just before it, and loses if a word like "created"
// or "issued" sits closer - "Created 2024-03-01 legacy webhook" is a birthday, not a
// deadline, and reporting it as expired 800 days ago would be worse than saying nothing.
// With no word either way, a bare ISO date counts, since nothing else in a credential
// name looks like 2026-08-01, while a bare 01/08/2026 could be anything.
const findExpiryInText = (text) => {
  const subject = String(text || '');
  if (!subject) return null;

  const dates = findDates(subject);
  if (!dates.length) return null;

  const labels = labelsIn(subject, labelSource, 'expiry')
    .concat(labelsIn(subject, vetoSource, 'veto'))
    .sort((a, b) => a.end - b.end);

  for (const d of dates) {
    const near = labels
      .filter((l) => d.index >= l.end && d.index - l.end <= cfg.label_max_gap)
      .sort((a, b) => b.end - a.end)[0];

    if (near && near.kind === 'expiry') return { dt: d.dt, matched: d.text, label: near.word };
    if (near) continue;
    if (cfg.accept_bare_iso_dates && d.iso) return { dt: d.dt, matched: d.text, label: null };
  }

  return null;
};

const findings = [];
const untracked = [];
const ignored = [];
const notExpirable = [];
const testUnavailable = [];
let okCount = 0;
let verifiedCount = 0;
let tokenPresentCount = 0;
const staleDates = [];

creds.forEach((c) => {
  if (ignoreRx.some((rx) => rx.test(String(c.name || '')))) {
    ignored.push({ name: c.name, type: c.type });
    return;
  }

  const expirable = canExpire(c.type);
  const presenceOnly = isOauthType(c.type);
  const test = testByCredId.get(String(c.id)) || null;
  const probe = probeById.get(String(c.id)) || null;
  const probeExpired = !!probe && probe.verdict === 'expired';
  // A provider rejection is proof, so it outranks any date and any presence check.
  const broken = probeExpired || (!!test && test.ran && norm(test.status) !== 'ok');

  let testVerdict = null;
  if (test && !test.ran) {
    // No verdict came back, so this credential was NOT checked.
    testVerdict = 'unavailable';
    testUnavailable.push({
      name: c.name,
      type: c.type,
      http: test.http,
      message: String(test.message || '').slice(0, 200),
    });
  } else if (test && test.ran && !broken) {
    // An OAuth type only proves a token is stored; anything else made a real call.
    testVerdict = presenceOnly ? 'token_present' : 'verified';
    if (presenceOnly) tokenPresentCount++;
    else verifiedCount++;
  } else if (broken) {
    testVerdict = 'failed';
  }

  let expiresAt = null;
  let expirySource = null;

  const hit = findExpiryInText(c.name);
  if (hit) {
    expiresAt = hit.dt;
    expirySource = hit.label ? 'name: "' + hit.label + ' ' + hit.matched + '"' : 'name: ' + hit.matched;
  } else {
    const lifetime = Number(cfg.type_lifetime_days[c.type]);
    const updated = c.updatedAt ? DateTime.fromISO(c.updatedAt, { zone: TZ }) : null;
    if (isFinite(lifetime) && lifetime > 0 && updated && updated.isValid) {
      expiresAt = updated.plus({ days: lifetime }).endOf('day');
      expirySource = lifetime + 'd ' + c.type + ' lifetime from last update ' + updated.toFormat('yyyy-LL-dd');
    }
  }

  const base = {
    probe_verdict: probe ? probe.verdict : null,
    probe_detail: probe ? probe.detail : '',
    probe_endpoint: probe ? probe.endpoint : '',
    credential_id: c.id,
    name: c.name,
    type: c.type,
    project: c.project,
    created_at: c.createdAt,
    updated_at: c.updatedAt,
    expiry_source: expirySource,
    can_expire: expirable,
    presence_check_only: presenceOnly,
    broken,
    test_verdict: testVerdict,
    test_status: test ? (test.ran ? test.status : 'Unavailable') : null,
    test_message: broken ? String(test.message || '').slice(0, 300) : '',
  };

  if (!expiresAt) {
    // No date to reason about. A failed test still makes it actionable today: for an
    // OAuth credential a failure means n8n holds no access token at all, so it was
    // never connected or was cleared - broken now, whatever any date would have said.
    if (probeExpired) {
      findings.push({ ...base, band: 'EXPIRED', expires_at: null, expires_on: null, days_left: null, sort_key: -2e6 });
    } else if (broken) {
      findings.push({ ...base, band: 'BROKEN', expires_at: null, expires_on: null, days_left: null, sort_key: -1e6 });
    } else if (expirable) {
      untracked.push({ credential_id: c.id, name: c.name, type: c.type });
    } else {
      // A plain API key has no expiry to miss, so chasing a date it cannot have would
      // only teach the reader to skim past the list.
      notExpirable.push({ name: c.name, type: c.type });
    }
    return;
  }

  const daysLeft = Math.floor(expiresAt.startOf('day').diff(today, 'days').days);
  let band;
  if (daysLeft < 0) band = 'EXPIRED';
  else if (daysLeft <= cfg.critical_within_days) band = 'CRITICAL';
  else if (daysLeft <= cfg.urgent_within_days) band = 'URGENT';
  else if (daysLeft <= cfg.warn_within_days) band = 'WARNING';
  else band = 'OK';

  // Evidence beats arithmetic. A token the provider just rejected is expired whatever
  // its name says; a token that still authenticates is not expired just because a
  // derived date ran out, and saying otherwise would train the reader to distrust this.
  if (probeExpired) band = 'EXPIRED';
  else if (probe && probe.verdict === 'live' && band === 'EXPIRED') band = 'STALE_DATE';

  if ((band === 'OK' || band === 'STALE_DATE') && !broken) {
    if (band === 'STALE_DATE') staleDates.push({ name: c.name, type: c.type, expires_on: expiresAt.toFormat('yyyy-LL-dd') });
    else okCount++;
    return;
  }

  findings.push({
    ...base,
    band: band === 'OK' ? 'BROKEN' : band,
    expires_at: expiresAt.toISO(),
    expires_on: expiresAt.toFormat('yyyy-LL-dd'),
    days_left: daysLeft,
    // A credential that fails its test is already failing in production, so it leads the
    // digest whatever its paper date says - a token rejected today is not a problem for
    // January. Time order still decides within each group.
    sort_key: probeExpired ? -2e6 + daysLeft : broken ? -1e6 + daysLeft : daysLeft,
  });
});

// Soonest first.
findings.sort((a, b) => a.sort_key - b.sort_key || String(a.name).localeCompare(String(b.name)));

const countBand = (b) => findings.filter((f) => f.band === b).length;
const stats = {
  run_at: now.toISO(),
  timezone: TZ,
  total_credentials: creds.length,
  findings: findings.length,
  expired: countBand('EXPIRED'),
  critical: countBand('CRITICAL'),
  urgent: countBand('URGENT'),
  warning: countBand('WARNING'),
  broken: countBand('BROKEN'),
  ok: okCount,
  untracked: untracked.length,
  ignored: ignored.length,
  not_expirable: notExpirable.length,
  expirable: creds.filter((c) => canExpire(c.type)).length,
  tested: testByCredId.size,
  verified: verifiedCount,
  token_present: tokenPresentCount,
  test_unavailable: testUnavailable.length,
  probes_run: probeById.size,
  probes_live: [...probeById.values()].filter((p) => p.verdict === 'live').length,
  probes_expired: [...probeById.values()].filter((p) => p.verdict === 'expired').length,
  probes_inconclusive: [...probeById.values()].filter((p) => p.verdict === 'inconclusive').length,
  probes_unconfigured: [...probeById.values()].filter((p) => p.verdict === 'unconfigured').length,
  stale_dates: staleDates.length,
  probes_drifted: probeDrift.length,
  unprobed: unprobedTypes.length,
  warn_within_days: cfg.warn_within_days,
  urgent_within_days: cfg.urgent_within_days,
  critical_within_days: cfg.critical_within_days,
};

console.log('evaluate_expiry: ' + JSON.stringify(stats));

const extras = {
  _stats: stats,
  _untracked: untracked,
  _ignored: ignored,
  _not_expirable: notExpirable,
  _test_unavailable: testUnavailable,
  _stale_dates: staleDates,
  _probe_drift: probeDrift,
  _unprobed: unprobedTypes,
  _probes: [...probeById.entries()].map(([id, p]) => ({
    credential_id: id,
    node: p.node,
    endpoint: p.endpoint,
    verdict: p.verdict,
    detail: p.detail,
  })),
};

if (!findings.length) {
  return [{ json: { no_findings: true, ...extras } }];
}

return findings.map((f, i) => ({ json: i === 0 ? { rank: 1, ...f, ...extras } : { rank: i + 1, ...f } }));

// Slack digest. The wording is deliberately different per band: an already dead or
// same-day credential has to read as "drop what you are doing", a 5-day one as a
// heads-up. Same message for both trains the reader to ignore it.
const items = $input.all().map((i) => i.json);
const first = items[0] || {};
const stats = first._stats || {};
const untracked = first._untracked || [];
const ignored = first._ignored || [];
const testUnavailable = first._test_unavailable || [];
const probes = first._probes || [];
const staleDates = first._stale_dates || [];
const probeDrift = first._probe_drift || [];
const unprobed = first._unprobed || [];
const cfg = $('parse_expiry_config').first().json;

const findings = first.no_findings ? [] : items;

const EMOJI = {
  EXPIRED: ':skull:',
  CRITICAL: ':rotating_light:',
  BROKEN: ':x:',
  URGENT: ':warning:',
  WARNING: ':hourglass_flowing_sand:',
};
const SEVERITY = ['EXPIRED', 'CRITICAL', 'BROKEN', 'URGENT', 'WARNING'];
const worst = SEVERITY.find((b) => findings.some((f) => f.band === b)) || null;

const when = (f) => {
  // Provider evidence, when there is any, is the headline - "expires in 2 days" next to a
  // skull reads as a contradiction when the token is already being refused.
  if (f.probe_verdict === 'expired') {
    return (
      '*rejected by the provider right now*' +
      (f.expires_on ? ' (its date said ' + f.expires_on + ')' : '')
    );
  }
  if (f.days_left === null || f.days_left === undefined) return 'no expiry date on record';
  if (f.days_left < 0) return '*expired ' + Math.abs(f.days_left) + ' day(s) ago* (' + f.expires_on + ')';
  if (f.days_left === 0) return '*expires TODAY* (' + f.expires_on + ')';
  if (f.days_left === 1) return '*expires TOMORROW* (' + f.expires_on + ')';
  return 'expires in *' + f.days_left + ' days* (' + f.expires_on + ')';
};

const action = (f) => {
  switch (f.band) {
    case 'EXPIRED':
      return f.probe_verdict === 'expired'
        ? 'The provider rejected this token just now, so every workflow using it is already failing. Reconnect the credential in n8n.'
        : 'Past its date - anything using it is likely failing already. Rotate it now.';
    case 'CRITICAL':
      return 'Rotate today, there is no margin left.';
    case 'BROKEN':
      return f.presence_check_only
        ? 'n8n holds no access token for this credential - it was never connected, or the token was cleared. Reconnect it.'
        : 'The provider rejected it, so it is broken regardless of its date - rotate or re-authenticate it.';
    case 'URGENT':
      return 'Rotate in the next couple of days.';
    default:
      return 'Put the rotation on this week.';
  }
};

const lines = [];

if (!findings.length) {
  lines.push(
    ':white_check_mark: *Credentials Review* - nothing expires within ' +
      stats.warn_within_days +
      ' days' +
      (stats.probes_live ? ', and ' + stats.probes_live + ' expirable credential(s) still authenticate with their provider' : '') +
      (stats.verified ? ', ' + stats.verified + ' API key(s) verified' : '') +
      '.'
  );
} else {
  const mention = cfg.slack_mention && ['EXPIRED', 'CRITICAL', 'BROKEN'].includes(worst) ? cfg.slack_mention + ' ' : '';
  if (worst === 'EXPIRED' || worst === 'CRITICAL' || worst === 'BROKEN') {
    lines.push(
      mention + ':rotating_light: *Credentials Review* - ' + findings.length + ' credential(s) need action *now*'
    );
  } else if (worst === 'URGENT') {
    lines.push(
      ':warning: *Credentials Review* - ' +
        findings.length +
        ' credential(s) expire within ' +
        stats.urgent_within_days +
        ' days'
    );
  } else {
    lines.push(
      ':hourglass_flowing_sand: *Credentials Review* - heads-up, ' +
        findings.length +
        ' credential(s) expire within ' +
        stats.warn_within_days +
        ' days'
    );
  }
  lines.push('');

  for (const f of findings) {
    lines.push((EMOJI[f.band] || ':grey_question:') + ' *' + f.rank + '. ' + f.name + '* - ' + when(f));
    const bits = ['type `' + f.type + '`'];
    if (f.project) bits.push('project ' + f.project);
    if (f.probe_verdict) bits.push('probe ' + f.probe_verdict + (f.probe_detail ? ' (' + f.probe_detail + ')' : ''));
    if (f.expiry_source) bits.push('read from ' + f.expiry_source);
    if (f.broken && f.test_message) bits.push('test: ' + f.test_message);
    lines.push('`' + bits.join('  |  ') + '`');
    lines.push('_' + action(f) + '_');
    lines.push('');
  }
  lines.push('_After rotating, update the date in the credential name and this stops nagging._');

  // A derived date is a guess about when the token was issued, and the reader has to
  // know that before trusting it: n8n never exposes the real expiry, and re-saving a
  // credential without reconnecting bumps updatedAt and silently moves the deadline.
  if (findings.some((f) => String(f.expiry_source || '').includes('lifetime from last update'))) {
    lines.push(
      '_Dates read from a `lifetime` are derived from the credential\'s last update, not from the token - n8n never exposes the real expiry. Editing and saving a credential without reconnecting it restarts that countdown._'
    );
  }
}

lines.push(
  '`' +
    stats.total_credentials +
    ' credentials · ' +
    stats.expired +
    ' expired · ' +
    stats.critical +
    ' critical · ' +
    stats.urgent +
    ' urgent · ' +
    stats.warning +
    ' warning · ' +
    stats.broken +
    ' broken · ' +
    stats.ok +
    ' ok · ' +
    stats.untracked +
    ' undated · ' +
    stats.not_expirable +
    ' cannot expire · ' +
    stats.ignored +
    ' ignored`'
);
lines.push(
  '`tested ' +
    (stats.tested || 0) +
    ' · ' +
    (stats.verified || 0) +
    ' verified with provider · ' +
    (stats.token_present || 0) +
    ' oauth token present but unverified · ' +
    (stats.broken || 0) +
    ' failed' +
    (stats.test_unavailable ? ' · ' + stats.test_unavailable + ' not checked' : '') +
    '`'
);

// The presence check is the single most misleading thing in this digest, so it gets
// said out loud every time it happened rather than buried in a node comment.
if (stats.token_present) {
  lines.push(
    '_`oauth token present but unverified`: for OAuth credentials n8n only checks that an access token is stored, with no call to the provider - a token that died months ago still answers OK. Their dates, not their test result, are the signal._'
  );
}

for (const d of probeDrift) {
  lines.push(
    ':rotating_light: *' +
      d.node +
      ' is bound to a credential that no longer exists* (id `' +
      d.bound +
      '`), so ' +
      d.type +
      ' was not verified at all. Open that node and select: ' +
      d.should_be
  );
}

for (const u of unprobed) {
  lines.push(
    ':grey_exclamation: *' + u.name + '* shares the type ' + u.type + ' with a probed credential, so it is dated but never verified. Give it its own probe node to cover it.'
  );
}

if (probes.length) {
  const byVerdict = (v) => probes.filter((p) => p.verdict === v);
  lines.push(
    '`probes ' +
      probes.length +
      ' · ' +
      byVerdict('live').length +
      ' live · ' +
      byVerdict('expired').length +
      ' expired · ' +
      byVerdict('inconclusive').length +
      ' inconclusive · ' +
      byVerdict('unconfigured').length +
      ' unconfigured`'
  );
  for (const p of byVerdict('unconfigured')) {
    lines.push(
      ':grey_exclamation: *' + p.node + ' has no credential selected* - open that node once in n8n and pick the ' + p.type + ' credential, or this type is never really checked.'
    );
  }
  for (const p of byVerdict('inconclusive')) {
    lines.push(
      ':grey_exclamation: *' + p.type + ' could not be verified this run* - ' + p.detail + ' (' + p.endpoint + '). Not treated as expired; a provider hiccup is not a dead token.'
    );
  }
}

if (staleDates.length) {
  lines.push(
    ':information_source: *Still working despite an expired date* - ' +
      staleDates.map((d) => d.name + ' (dated ' + d.expires_on + ')').join(', ')
  );
  lines.push(
    '_The provider still accepts the token, so the date is what is wrong. It was probably reconnected without updating the name - fix the date and this stops._'
  );
}

if (testUnavailable.length) {
  const first_ = testUnavailable[0];
  lines.push(
    ':grey_exclamation: *' +
      testUnavailable.length +
      ' credential(s) were not actually checked* - ' +
      testUnavailable
        .slice(0, 6)
        .map((u) => u.name)
        .join(', ') +
      (testUnavailable.length > 6 ? ' … +' + (testUnavailable.length - 6) + ' more' : '')
  );
  lines.push(
    '_The test returned no verdict' +
      (first_.http ? ' (HTTP ' + first_.http + ': ' + first_.message + ')' : ': ' + first_.message) +
      '. A 403 means the n8n API key is missing the `credential:read` scope - until that is fixed, silence here does not mean healthy._'
  );
}

if (cfg.report_untracked && untracked.length) {
  const shown = untracked.slice(0, 12).map((u) => u.name + ' (' + u.type + ')');
  lines.push(
    ':question: *No expiry date, but can expire* - ' +
      untracked.length +
      ': ' +
      shown.join(', ') +
      (untracked.length > shown.length ? ' … +' + (untracked.length - shown.length) + ' more' : '')
  );
  lines.push(
    '_A stored token is not a date - n8n only proves one exists, never that it is still good. Rename the credential in n8n to carry its date - `Some account (expires 2026-08-01)` - or add its type to `type_lifetime_days`._'
  );
}

if (!stats.tested) {
  lines.push(
    '_No credential was tested this run: nothing matched `test_type_patterns`, so only dates were checked._'
  );
}

return [
  {
    json: {
      digest_text: lines.join('\n'),
      should_notify: findings.length > 0 || cfg.notify_when_clean === true,
      findings_count: findings.length,
      worst_band: worst,
      _stats: stats,
      _ignored: ignored,
    },
  },
];
